document.addEventListener('DOMContentLoaded', function () {
  const tabWrapper = document.querySelector('.tab-evertec-microsoft');
  if (!tabWrapper) return;

  const tabs = tabWrapper.querySelectorAll('.e-n-tab-title');
  const nextBtn = document.querySelector('.btn-microsoft.after');
  const prevBtn = document.querySelector('.btn-microsoft.before');

  function activateTab(index) {
    if (index < 0 || index >= tabs.length) return;

    tabs[index].click();
  }

  function getActiveIndex() {
    return Array.from(tabs).findIndex(tab => tab.getAttribute('aria-selected') === 'true');
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', () => {
      const currentIndex = getActiveIndex();
      if (currentIndex < tabs.length - 1) {
        activateTab(currentIndex + 1);
      }
    });
  }

  if (prevBtn) {
    prevBtn.addEventListener('click', () => {
      const currentIndex = getActiveIndex();
      if (currentIndex > 0) {
        activateTab(currentIndex - 1);
      }
    });
  }
});
